<template><main class="ccd-page community-page"><ConnectedDemoHeader icon="♣" title="Connected Community" subtitle="Demo data · Twitch, Discord and Respawn in one community"/><section class="ccd-grid ccd-metrics"><ConnectedDemoMetric icon="♙" label="Total Members" :value="metrics.total.toLocaleString()" detail="All platforms"/><ConnectedDemoMetric icon="↗" label="Connected Members" :value="metrics.connected.toLocaleString()" detail="Across visible platforms" :highlight="demo.connectedHighlight"/><ConnectedDemoMetric icon="✦" label="Community Score" :value="metrics.score" detail="Out of 100"/><ConnectedDemoMetric icon="♢" label="Data Confidence" :value="`${metrics.confidence}%`" detail="Coverage and reliability"/></section><section class="community-layout"><div class="community-main"><section class="ccd-card connection-card"><div class="card-title"><div><h2>Community Connection ⓘ</h2><p class="ccd-card-sub">Overlap of members across platforms</p></div><div class="ccd-tabs"><button v-for="p in platforms" :key="p.id" class="ccd-tab" :class="{active:demo.visiblePlatforms.includes(p.id)}" @click="toggleDemoPlatform(p.id)">{{ p.label }}</button></div></div><div class="connection-content"><ul class="ccd-list platform-totals"><li v-for="p in visibleDetails" :key="p.id"><span class="ccd-platform"><i>{{p.icon}}</i><span>{{p.label}}<strong>{{p.members}}</strong></span></span></li></ul><div class="venn" :class="`count-${demo.visiblePlatforms.length}`"><i class="circle twitch">Twitch</i><i class="circle discord">Discord</i><i class="circle respawn">Project<br>Respawn</i><strong>Connected<br><b>{{metrics.connected.toLocaleString()}}</b></strong></div></div></section><section class="ccd-card health"><h2>Community Health ⓘ</h2><p class="ccd-card-sub">Score breakdown</p><div v-for="item in health" :key="item.label" class="health-row"><span>{{item.icon}}</span><div><b>{{item.label}}</b><small>{{item.detail}}</small></div><strong>{{item.value}} <small>/ 100</small></strong><div class="ccd-progress"><i :style="{width:`${item.value}%`}"></i></div></div></section><section class="ccd-card growth"><h2>Member Growth ⓘ</h2><p class="ccd-card-sub">New members over time</p><svg viewBox="0 0 600 235" role="img" aria-label="Deterministic member growth chart"><g class="chart-grid"><path v-for="y in [35,80,125,170,215]" :key="y" :d="`M30 ${y}H580`"/></g><polyline points="30,185 85,170 140,155 195,130 250,112 305,96 360,82 415,65 470,48 525,38 580,22" class="total"/><polyline points="30,205 85,188 140,174 195,155 250,143 305,132 360,118 415,108 470,94 525,78 580,62" class="twitch-line"/><polyline points="30,218 85,207 140,198 195,184 250,174 305,164 360,152 415,140 470,130 525,116 580,102" class="discord-line"/></svg><div class="chart-legend"><span>● Total</span><span>● Twitch</span><span>● Discord</span></div></section><section class="ccd-card"><h2>Recent Community Activity ⓘ</h2><ul class="ccd-list"><li v-for="item in demo.activity.slice(0,4)" :key="item.id"><span class="activity-icon">{{item.icon}}</span><div><b>{{item.title}}</b><small>{{item.detail}} · {{item.time}}</small></div></li></ul></section><section class="ccd-card"><h2>Community Goals ⓘ</h2><p class="ccd-card-sub">Progress to next milestones</p><div v-for="goal in goals" :key="goal.label" class="goal"><b>{{goal.label}}</b><span>{{goal.detail}}</span><div class="ccd-progress"><i :style="{width:goal.value+'%'}"></i></div><small>{{goal.value}}%</small></div></section></div><aside class="community-rail"><section class="ccd-card demo-action"><b>INTERACTIVE DEMO</b><p>Highlight the Connected Members metric and community milestone.</p><button class="ccd-button primary" @click="highlightConnectedMembers">✦ Highlight Connected Members</button></section><section class="ccd-card milestone" :class="{active:demo.milestoneHighlight}"><span>🎉</span><div><small>MILESTONE</small><strong>1,100</strong><p>members connected<br>across platforms</p></div></section><section class="ccd-card"><h2>Your Community Story</h2><div class="nova"><span>N</span><strong>Nova#1234</strong></div><ul class="ccd-list"><li v-for="identity in demo.nova.identities" :key="identity.platform"><span class="ccd-platform"><i>{{platformIcon(identity.platform)}}</i>{{identity.label}}</span><b class="ccd-positive">Connected ✓</b></li><li><span>▣ Friday Game Night</span><b>{{demo.event.attended?'Attended':demo.event.rsvp?'Going':'Not RSVP’d'}}</b></li><li><span>✦ Points balance</span><b>{{demo.nova.balance.toLocaleString()}}</b></li><li><span>🏆 Community Regular</span><b>{{demo.achievement.unlocked?'Unlocked':demo.achievement.progress+' / 5'}}</b></li></ul></section><section class="ccd-card"><h2>Platform Breakdown ⓘ</h2><div v-for="p in platforms" :key="p.id" class="breakdown"><span class="ccd-platform"><i>{{p.icon}}</i>{{p.label}}</span><strong>{{p.members}}</strong><div class="ccd-progress"><i :style="{width:p.percent+'%'}"></i></div></div></section></aside></section><footer class="ccd-footer-note">ⓘ All identities are fictional. Connections are member-authorised; Data Confidence describes coverage and reliability, not personal surveillance.</footer></main></template>
<script setup>import{computed}from'vue';import ConnectedDemoHeader from'../../connected-demo/ConnectedDemoHeader.vue';import ConnectedDemoMetric from'../../connected-demo/ConnectedDemoMetric.vue';import{connectedDemo as demo,communityMetrics,highlightConnectedMembers,toggleDemoPlatform}from'../../connected-demo/connectedDemoState.js';import'../../connected-demo/connectedDemo.css';const platforms=[{id:'twitch',label:'Twitch',icon:'▣',members:'1,940',percent:68},{id:'discord',label:'Discord',icon:'☁',members:'1,670',percent:59},{id:'respawn',label:'Respawn',icon:'R',members:'1,284',percent:45}];const metrics=computed(()=>communityMetrics(demo));const visibleDetails=computed(()=>platforms.filter(p=>demo.visiblePlatforms.includes(p.id)));const health=[['♡','Retention','Members returning',82],['♙','Participation','Members engaging',79],['☺','Positive interactions','Positive vs. negative',88],['♢','Safety','Community is safe',93]].map(([icon,label,detail,value])=>({icon,label,detail,value}));const goals=[{label:'Grow our connected community',detail:`${metrics.value.connected.toLocaleString()} / 1,500 members`,value:75},{label:'Increase weekly participation',detail:'3,210 / 4,000 actions',value:80},{label:'Positive interactions target',detail:'88% / 90%',value:98}];function platformIcon(id){return platforms.find(p=>p.id===id)?.icon||'•'}</script>
<style scoped>.community-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:12px}.community-main{display:grid;grid-template-columns:1.6fr 1fr;gap:12px}.connection-card{min-height:300px}.card-title{display:flex;justify-content:space-between;gap:12px}.connection-content{display:grid;grid-template-columns:170px 1fr;align-items:center}.platform-totals strong{display:block;font-size:18px}.venn{position:relative;width:390px;height:245px;margin:auto}.circle{position:absolute;display:grid;width:165px;height:165px;place-items:center;border:2px solid;border-radius:50%;background:rgba(40,90,170,.23);font-style:normal;text-align:center}.twitch{left:110px;top:0;border-color:#ca65ff}.discord{left:35px;top:75px;border-color:#4894ff}.respawn{left:185px;top:75px;border-color:#48dfd1}.venn>strong{position:absolute;z-index:2;left:145px;top:105px;text-align:center}.venn>strong b{font-size:22px}.venn.count-1 .circle,.venn.count-2 .circle{opacity:.28}.health-row{display:grid;grid-template-columns:34px 1fr auto;gap:8px;align-items:center;margin:12px 0}.health-row>span{font-size:22px}.health-row small{display:block;color:#91a2ba}.health-row>.ccd-progress{grid-column:2/4}.growth svg{width:100%;height:235px}.chart-grid path{stroke:#223954;stroke-width:1}.growth polyline{fill:none;stroke-width:3}.total{stroke:#b7c2d4;stroke-dasharray:5}.twitch-line{stroke:#a64be4}.discord-line{stroke:#3e8cff}.chart-legend{display:flex;gap:18px;color:#9eacc1}.community-rail{display:grid;align-content:start;gap:12px}.demo-action b{color:#c084fc}.demo-action .ccd-button{width:100%}.milestone{display:flex;align-items:center;justify-content:center;gap:18px;text-align:left}.milestone.active{border-color:#a557e7;box-shadow:0 0 28px rgba(165,87,231,.3)}.milestone>span{font-size:48px}.milestone small,.milestone strong{display:block}.milestone strong{font-size:34px}.milestone p{margin:0}.nova{display:flex;align-items:center;gap:10px;padding:10px 0}.nova span{display:grid;width:42px;height:42px;place-items:center;border-radius:50%;background:#5c2a9e}.breakdown{display:grid;grid-template-columns:1fr auto;gap:6px;margin:12px 0}.breakdown .ccd-progress{grid-column:1/-1}.activity-icon{display:grid;width:30px;height:30px;place-items:center;border-radius:50%;background:#20124c}.goal{display:grid;grid-template-columns:1fr auto;gap:6px;margin:18px 0}.goal span{grid-column:1/-1;color:#9ba9bd}.goal .ccd-progress{grid-column:1}.goal small{color:#aebbd0}@media(max-width:1450px){.community-layout{grid-template-columns:1fr}.community-rail{grid-template-columns:repeat(3,1fr)}.community-rail>*:last-child{grid-column:1/-1}}@media(max-width:900px){.community-main,.community-rail{grid-template-columns:1fr}.connection-content{grid-template-columns:1fr}.venn{transform:scale(.82);transform-origin:center}.community-rail>*:last-child{grid-column:auto}}</style>
